from typing import List, Optional

from fastapi import APIRouter, Depends, HTTPException
from sqlalchemy.orm import Session

import crud
import schemas
from database import get_db
from models import Tag

router = APIRouter()


@router.get("/", response_model=List[schemas.Tag])
def list_tags(
    sys_code: Optional[str] = None,
    subsys_code: Optional[str] = None,
    skip: int = 0,
    limit: int = 100,
    db: Session = Depends(get_db),
):
    query = db.query(Tag)
    if sys_code:
        query = query.filter(Tag.sys_code == sys_code)
    if subsys_code:
        query = query.filter(Tag.subsys_code == subsys_code)
    return query.offset(skip).limit(limit).all()


@router.get("/{sys_code}/{subsys_code}/{tag_no}", response_model=schemas.Tag)
def get_tag(sys_code: str, subsys_code: str, tag_no: str, db: Session = Depends(get_db)):
    tag = crud.get_tag_by_composite(db, sys_code=sys_code, subsys_code=subsys_code, tag_no=tag_no)
    if not tag:
        raise HTTPException(status_code=404, detail="Tag not found")
    return tag
